<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Public survey reports</title><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="<?= base_url('css/enterprise-pages.css?v=20260701-2') ?>" rel="stylesheet"><link href="<?= base_url('css/report-suite.css?v=20260811-1') ?>" rel="stylesheet"></head><body>
<header class="topbar"><div class="brand-row"><a class="brand-mark" href="<?= site_url('dashboard') ?>">LMS CI4</a><div class="brand-center">E-LEARNING</div><div class="brand-actions"><span><?= esc($name ?? '-') ?></span><a href="<?= site_url('logout') ?>"><i class="bi bi-box-arrow-right"></i> Logout</a></div></div></header>
<main class="page report-page"><div class="head report-head"><div class="report-title-wrap"><div class="report-title-icon"><i class="bi bi-clipboard-data"></i></div><div><div class="kicker">Survey reports</div><h1>Public survey reports</h1><p class="sub report-description">Review response volume and open detailed participation reports.</p></div></div><div class="report-head-actions"><a class="btn" href="<?= site_url('dashboard') ?>"><i class="bi bi-grid"></i> Dashboard</a></div></div>
<section class="metrics report-metrics"><div class="metric report-metric"><div class="report-metric__top"><span>Total surveys</span><i class="bi bi-ui-checks-grid report-metric__icon"></i></div><strong><?= count($surveys ?? []) ?></strong></div><div class="metric report-metric"><div class="report-metric__top"><span>Total responses</span><i class="bi bi-people report-metric__icon"></i></div><strong><?= array_sum(array_map(static fn($s)=>(int)($s['responses'] ?? 0), $surveys ?? [])) ?></strong></div></section>
<section class="panel report-panel"><div class="toolbar report-toolbar"><div><p class="report-toolbar__title">All survey reports</p><p class="report-toolbar__hint"><?= count($surveys ?? []) ?> surveys available</p></div></div><div class="table-wrap report-table-wrap"><table class="report-table"><thead><tr><th>ID</th><th>Survey</th><th>Responses</th><th>Actions</th></tr></thead><tbody><?php foreach(($surveys ?? []) as $s): ?><tr><td><span class="badge">#<?= esc($s['sv_id']) ?></span></td><td><span class="report-primary"><?= esc($s['title']) ?></span></td><td><span class="report-score"><?= esc($s['responses']) ?></span> <span class="report-secondary">submissions</span></td><td><div class="actions"><a class="btn" href="<?= site_url('survey/report/'.$s['sv_id']) ?>"><i class="bi bi-bar-chart"></i> View report</a><a class="btn" href="<?= site_url('survey/report/'.$s['sv_id'].'/export') ?>"><i class="bi bi-download"></i> CSV</a></div></td></tr><?php endforeach ?><?php if(empty($surveys)): ?><tr><td colspan="4" class="report-empty"><div class="report-empty__icon"><i class="bi bi-clipboard-x"></i></div><strong>No survey reports yet</strong><span class="muted">Reports appear here after surveys are created.</span></td></tr><?php endif ?></tbody></table></div></section></main><script src="<?= base_url('js/enterprise-pages.js?v=20260701-3') ?>"></script></body></html>
